package th.co.scgroup1989.scpda;
import com.sun.net.httpserver.*;
import org.json.*;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
// Host-side QA only. Not compiled into the APK. The shipping HttpsWire stays fixed.
public final class NativeReadHarness {
 static final class SoftwareDevice implements StockDaySession.DeviceProof {
  final java.nio.file.Path root;final java.security.KeyPair pair;final String id;
  SoftwareDevice(java.nio.file.Path r)throws Exception{root=r;java.nio.file.Files.createDirectories(r);java.nio.file.Path secret=r.resolve("test-device-private.pk8"),pub=r.resolve("test-device-public.spki"),identity=r.resolve("test-device-id.txt");if(java.nio.file.Files.exists(secret)){java.security.KeyFactory f=java.security.KeyFactory.getInstance("EC");pair=new java.security.KeyPair(f.generatePublic(new java.security.spec.X509EncodedKeySpec(java.nio.file.Files.readAllBytes(pub))),f.generatePrivate(new java.security.spec.PKCS8EncodedKeySpec(java.nio.file.Files.readAllBytes(secret))));id=java.nio.file.Files.readString(identity);}else{java.security.KeyPairGenerator g=java.security.KeyPairGenerator.getInstance("EC");g.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));pair=g.generateKeyPair();id=java.util.UUID.randomUUID().toString();java.nio.file.Files.write(secret,pair.getPrivate().getEncoded());java.nio.file.Files.write(pub,pair.getPublic().getEncoded());java.nio.file.Files.writeString(identity,id);}}
  public String publicKey(){return java.util.Base64.getEncoder().encodeToString(pair.getPublic().getEncoded());}public String deviceId(){return id;}public String certificate(){try{return java.nio.file.Files.readString(root.resolve("test-device-cert.txt"));}catch(Exception e){return "";}}public void saveCertificate(String c){try{java.nio.file.Files.writeString(root.resolve("test-device-cert.txt"),c);}catch(Exception e){throw new RuntimeException(e);}}public String sign(String text)throws Exception{java.security.Signature s=java.security.Signature.getInstance("SHA256withECDSA");s.initSign(pair.getPrivate());s.update(text.getBytes(java.nio.charset.StandardCharsets.UTF_8));return java.util.Base64.getEncoder().encodeToString(s.sign());}
 }
 public static void main(String[] args)throws Exception{final String origin=args[0];if(!origin.matches("http://127\\.0\\.0\\.1:[0-9]+"))throw new Exception("Explicit loopback fixture required");final StockDaySession session=new StockDaySession((method,path,body,headers,jar)->{
  URL url=new URL(origin+path);HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(10000);c.setRequestMethod(method);for(Map.Entry<String,List<String>> h:jar.get(url.toURI(),Collections.emptyMap()).entrySet())c.setRequestProperty(h.getKey(),String.join("; ",h.getValue()));for(Map.Entry<String,String> h:headers.entrySet())c.setRequestProperty(h.getKey(),h.getValue());try{if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.toString().getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();jar.put(url.toURI(),c.getHeaderFields());InputStream in=status>=400?c.getErrorStream():c.getInputStream();String text=in==null?"{}":new String(in.readAllBytes(),StandardCharsets.UTF_8);return new StockDaySession.Reply(status,new JSONObject(text));}finally{c.disconnect();}
 },new SoftwareDevice(java.nio.file.Paths.get(args[1])));HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/invoke",x->{JSONObject reply=new JSONObject();try{JSONObject request=new JSONObject(new String(x.getRequestBody().readAllBytes(),StandardCharsets.UTF_8));String op=request.getString("op");JSONObject result=op.equals("activateDevice")?session.activate(new JSONObject(java.nio.file.Files.readString(java.nio.file.Paths.get(args[2])))):session.execute(op,request.optJSONObject("body")==null?new JSONObject():request.getJSONObject("body"));reply.put("ok",true).put("data",result);}catch(Exception e){reply.put("ok",false).put("status",e instanceof StockDaySession.ApiError?((StockDaySession.ApiError)e).status:0).put("code",e instanceof StockDaySession.ApiError?((StockDaySession.ApiError)e).code:"QA_ERROR").put("error",e.getMessage());}byte[] b=reply.toString().getBytes(StandardCharsets.UTF_8);x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});server.start();System.out.println(new JSONObject().put("port",server.getAddress().getPort()).put("testOnly",true));}
}
